def update_test_file():
    """Update the test file with new precise expected values."""
    test_file_path = r"C:\Github\automatisch-toetsmodel-plaatbruggen\tests\test_src\test_integrations\test_scia_elem_des_mag.py"
    
    with open(test_file_path, 'r', encoding='utf-8') as f:
        content = f.read()
    
    # Pattern to match test case dictionaries
    pattern = r'(\{"load_case": "([^"]+)", "mx": [^,]+, "my": [^,]+, "mxy": [^,]+, "vx": [^,]+, "vy": [^,]+, "nx": [^,]+, "ny": [^,]+, "nxy": [^,]+, )"expected_mxd_plus": [^,]+, "expected_mxd_minus": [^,]+, "expected_myd_plus": [^,]+, "expected_myd_minus": [^,]+, "expected_nxd": [^,]+, "expected_nyd": [^}]+(\},)'
    
    def replacer(match):
        prefix = match.group(1)
        load_case = match.group(2)
        suffix = match.group(3)
        
        if load_case in EXPECTED_VALUES:
            expected = EXPECTED_VALUES[load_case]
            return (f'{prefix}'
                    f'"expected_mxd_plus": {expected[0]}, "expected_mxd_minus": {expected[1]}, '
                    f'"expected_myd_plus": {expected[2]}, "expected_myd_minus": {expected[3]}, '
                    f'"expected_nxd": {expected[4]}, "expected_nyd": {expected[5]}{suffix}')
        else:
            # Return original match if load_case not in our dictionary
            return match.group(0)
    
    # Apply replacements
    updated_content = re.sub(pattern, replacer, content)
    
    # Write back to file
    with open(test_file_path, 'w', encoding='utf-8') as f:
        f.write(updated_content)
    
    print(f"Successfully updated expected values in {test_file_path}")
    print(f"Updated {len(EXPECTED_VALUES)} test cases with precise expected values")


if __name__ == "__main__":
    update_test_file()
